#!/usr/bin/env python3
"""Install and run REAL task-sync acceptance. No mocks, no credential prompts."""
import base64, datetime, json, os, shutil, subprocess, tempfile, time
from pathlib import Path
import urllib.request
import yaml
ROOT=Path('/opt/jarlhalla/app')
AI=Path('/opt/jarlhalla-ai')
BUNDLE=ROOT/'command-task-sync'
COMPOSE=ROOT/'docker-compose.yml'
DROPIN=Path('/etc/systemd/system/jarlhalla-ai.service.d/95-task-sync.conf')
KEYFILE=Path('/etc/jarlhalla-ai-gateway.env')
CONTAINER='jarlhalla-control-gateway'
PAYLOADS={'jarlhalla_task_sync.py': '', 'console_task_routes.py': '', 'jarlhalla_console.html': '', 'verify_task_sync.py': ''}

def run(args):
    p=subprocess.run(args,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    if p.returncode:raise RuntimeError('Command failed: '+args[0])

def private_write(path,text):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(dir=path.parent)
    with os.fdopen(fd,'w') as f:f.write(text)
    os.chmod(tmp,0o600);os.replace(tmp,path)

def env():
    data=json.loads(subprocess.check_output(['docker','inspect',CONTAINER],text=True))[0]
    return dict(x.split('=',1) for x in data['Config']['Env'] if '=' in x)

def gateway_up():
    run(['docker','compose','-f',str(COMPOSE),'up','-d','--no-deps','--force-recreate','gateway'])
    for _ in range(30):
        try:
            with urllib.request.urlopen('http://127.0.0.1:8080/health',timeout=2) as res:
                if json.load(res).get('ok') is True:return
        except Exception:pass
        time.sleep(1)
    raise RuntimeError('Gateway health did not recover')

def main():
    if os.geteuid()!=0:raise RuntimeError('Run as root')
    settings=env();key=settings.get('JCC_API_KEY','').strip();token=settings.get('NOTION_TOKEN','').strip()
    if not key or not token:raise RuntimeError('Existing gateway credentials missing. Nothing changed.')
    # Verify real database access BEFORE changing any local files.
    req=urllib.request.Request('https://api.notion.com/v1/data_sources/aaa9420a-4015-4bdb-b942-59ad083bf347',
        headers={'Authorization':'Bearer '+token,'Notion-Version':'2025-09-03'})
    with urllib.request.urlopen(req,timeout=20) as res:schema=json.load(res)['properties']
    for name,kind in [('Task','title'),('Status','select'),('Source URL','url')]:
        if schema.get(name,{}).get('type')!=kind:raise RuntimeError('Live Notion schema differs. Nothing changed.')
    print('PASS: live Notion task-register access and schema',flush=True)
    backup=Path(tempfile.mkdtemp(prefix='jarlhalla-task-sync-',dir='/root'));backup.chmod(0o700)
    files=[COMPOSE,AI/'app.py',AI/'console_task_routes.py',AI/'jarlhalla_console.html',DROPIN,KEYFILE]
    had_bundle=BUNDLE.exists()
    if had_bundle:shutil.copytree(BUNDLE,backup/'bundle')
    saved=[]
    for n,path in enumerate(files):
        saved.append((path,path.exists(),backup/str(n)))
        if path.exists():shutil.copy2(path,backup/str(n))
    try:
        BUNDLE.mkdir(exist_ok=True)
        for name,value in PAYLOADS.items():(BUNDLE/name).write_bytes(base64.b64decode(value))
        source=subprocess.check_output(['docker','exec',CONTAINER,'cat','/app/main.py'],text=True)
        marker='from jarlhalla_task_sync import make_router as make_task_router'
        if marker not in source:source+='\n'+marker+'\napp.include_router(make_task_router(require_api_key))\n'
        compile(source,'gateway-main.py','exec')
        (BUNDLE/'gateway_main.py').write_text(source)
        conf=yaml.safe_load(COMPOSE.read_text());service=conf['services']['gateway']
        volumes=service.get('volumes',[])
        targets=['/app/main.py','/app/jarlhalla_task_sync.py','/jcc-task-sync-state']
        def target(v):return v.get('target') if isinstance(v,dict) else v.split(':')[1] if ':' in v else ''
        volumes=[v for v in volumes if target(v) not in targets]
        state=ROOT/'task-sync-state';state.mkdir(mode=0o700,exist_ok=True)
        uid=int(subprocess.check_output(['docker','exec',CONTAINER,'id','-u'],text=True).strip())
        gid=int(subprocess.check_output(['docker','exec',CONTAINER,'id','-g'],text=True).strip())
        os.chown(state,uid,gid)
        for host,dest,readonly in [(BUNDLE/'gateway_main.py','/app/main.py',True),(BUNDLE/'jarlhalla_task_sync.py','/app/jarlhalla_task_sync.py',True),(state,'/jcc-task-sync-state',False)]:
            volumes.append({'type':'bind','source':str(host),'target':dest,'read_only':readonly})
        service['volumes']=volumes
        COMPOSE.write_text(yaml.safe_dump(conf,sort_keys=False))
        for path in BUNDLE.iterdir():
            if path.is_file():path.chmod(0o644)
        shutil.copy2(BUNDLE/'console_task_routes.py',AI/'console_task_routes.py')
        shutil.copy2(BUNDLE/'jarlhalla_console.html',AI/'jarlhalla_console.html')
        app=(AI/'app.py').read_text();marker='from console_task_routes import router as notion_task_router'
        if marker not in app:app+='\n'+marker+'\napp.include_router(notion_task_router)\n'
        compile(app,'app.py','exec');(AI/'app.py').write_text(app)
        private_write(KEYFILE,'JARLHALLA_GATEWAY_KEY='+key+'\n')
        private_write(DROPIN,'[Service]\nEnvironmentFile='+str(KEYFILE)+'\n')
        run([str(AI/'venv/bin/python'),'-m','py_compile',str(AI/'app.py'),str(AI/'console_task_routes.py')])
        run(['docker','compose','-f',str(COMPOSE),'config','--quiet'])
        gateway_up()
        run(['systemctl','daemon-reload']);run(['systemctl','restart','jarlhalla-ai.service'])
        ready=False
        for _ in range(25):
            try:
                with urllib.request.urlopen('http://127.0.0.1:8787/workspace',timeout=2) as res:
                    if 'taskFeedback' in res.read().decode():ready=True;break
            except Exception:pass
            time.sleep(1)
        if not ready:raise RuntimeError('Workspace did not recover')
    except Exception:
        for path,existed,copy in reversed(saved):
            if existed:shutil.copy2(copy,path)
            else:path.unlink(missing_ok=True)
        if had_bundle:
            shutil.rmtree(BUNDLE);shutil.copytree(backup/'bundle',BUNDLE)
        # Persistent idempotency state is intentionally never deleted.
        try:gateway_up();run(['systemctl','daemon-reload']);run(['systemctl','restart','jarlhalla-ai.service'])
        except Exception:print('WARNING: check service health after rollback',flush=True)
        raise RuntimeError('Installation failed; previous configuration restored. Backup: '+str(backup)) from None
    print('PASS: installed. Backup: '+str(backup),flush=True)
    print('Running REAL acceptance: one marked task in Jarlhalla Tasks.',flush=True)
    result=subprocess.run(['python3',str(BUNDLE/'verify_task_sync.py')],stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True)
    print(result.stdout,flush=True)
    if result.returncode:raise RuntimeError('Installed, but live acceptance FAILED. Do not claim task sync verified; retain idempotency state.')
    # Verify the workspace proxy can read the same live task without exposing keys.
    from uuid import uuid5,NAMESPACE_URL
    task_id=str(uuid5(NAMESPACE_URL,'https://jarlhalla.com/command-center/notion-live-verification-v1'))
    with urllib.request.urlopen('http://127.0.0.1:8787/workspace/notion/tasks/'+task_id,timeout=120) as response:
        assert json.load(response).get('done') is True
    print('PASS: real task is readable through Command Center proxy',flush=True)
    print('Open http://127.0.0.1:18787/workspace#taskPanel',flush=True)

if __name__=='__main__':
    try:main()
    except Exception as exc:
        if isinstance(exc,RuntimeError):print('STOP:',str(exc))
        else:print('STOP:',type(exc).__name__,'(details suppressed)')
        raise SystemExit(1)
